(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-23' and end_date = '2025-04-23')
and start_date = '2025-04-23' and end_date = '2025-04-23'

/* cppi::3ee4ffc0e49e83f48ef1a7d5b5807a2a946d619a120a332217d603a72c28bf64 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-25' and end_date = '2025-04-25')
and start_date = '2025-04-25' and end_date = '2025-04-25'

/* cppi::28c97899ce726566a30e42d52a4e5059ad8b5d8349d966bf09d3b1c9ba45f4f3 */
select business_date as date_, security_id, 'SP500_45' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-25' and business_date <= date '2025-06-25' and weight_ndo>0 and id_cppib_index = 'SP500_45_GR_USD_0_0' and security_id is not null

/* cppi::e23d641afba1515324e7b06ce60d825108fb68e19777c318375671450db75899 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-27' and end_date = '2025-05-27')
and start_date = '2025-05-27' and end_date = '2025-05-27'

